/** Boundary fixtures are explicit; actual model/Chromium workflows are tested separately. */
public class Domain044Test {
 static JSONObject task(String family){return new JSONObject().put("family044",family).put("goal","Boundary fixture").put("model","fixture").put("recent",new JSONArray()).put("context044",new JSONObject()).put("nativeTrace044",new JSONArray()).put("nativeReplies044",new JSONObject()).put("requested044",new JSONObject());}
 static Domain044 domain(WorkspaceStore s){return new Domain044((r,a)->new JSONObject(),s);}
 @Test public void javaRoutesEveryFormerDesktopFamilyWithoutChangingWebCreation(){var b=new JSONObject().put("knowledge",new JSONObject()).put("tabletop",new JSONObject());String[][] examples={{"Read the continuing Java agent heartbeat","agent"},{"Explain measured mat alignment","alignment"},{"Show linked views","runtime"},{"What tools can you use?","self"},{"Research this selected lighter object","knowledge"},{"Where is the tabletop lighter?","tabletop"},{"Explain observed world footage","observations"},{"Arrange the same world","world"},{"Compare the pose controller","poseStudy"},{"Arrange these objects","pose"},{"Compare the contact controller","contact"},{"Evaluate pushing profile experience","force"},{"Push the crate","push"},{"Compile the playable map","map"},{"Generate 4D procedural space","space"},{"Run an evidence workflow","workflow"},{"Create and verify a durable app","creation"},{"Compare tracker profiles","tracking"},{"Browser detect objects","perception"},{"Move the imported 3d scene","spatial"},{"Analyze this motion dataset","data"},{"Predict block motion with the world model","goal"},{"Grab and release the native block","body"},{"Export the native scene","transfer"},{"Move the native camera once","observer"},{"Calibrate the physics ramp","calibration"},{"Simulate the physics ramp","scene"},{"Build a website about physics","workbench"}};for(var e:examples)assertEquals(e[0],e[1],ChatPolicy044.route(e[0],b,false));assertEquals("alignment",ChatPolicy044.route("Where is my lighter?",b,true));assertEquals("knowledge",ChatPolicy044.route("Research the lighter online",b,true));}
 @Test public void typedOptionsPreserveExplicitValuesAndRejectContradictions(){var required=Requested044.fields("Use 30 degrees, friction .2, target 1.4 and -0.3 m/s disturbance; save skill as exact-run","goal");assertEquals(30,required.getDouble("angleDeg"),0);assertEquals(-.3,required.getDouble("disturbanceMps"),0);assertEquals("exact-run",required.getString("saveSkillName"));assertThrows(IllegalArgumentException.class,()->Requested044.preserve(new JSONObject().put("targetM",2),required));assertEquals(1.4,Requested044.preserve(new JSONObject(),required).getDouble("targetM"),0);}
 @Test public void reportStageCannotSkipActualReads(){var g=task("agent");assertEquals(List.of("agent.read"),ChatPolicy044.allowed(g));g.getJSONObject("context044").put("agent042Facts",new JSONObject());assertEquals(List.of("agent.report"),ChatPolicy044.allowed(g));g.getJSONObject("context044").put("agent042Report",new JSONObject());assertEquals(List.of("finish"),ChatPolicy044.allowed(g));}
 @Test public void inventedHostFactsDoNotReplaceActualJavaRead()throws Exception{try(var s=new WorkspaceStore(Files.createTempDirectory("domain044-read-"))){var d=domain(s);var g=task("agent");d.noteNative(g,"/api/agent042/state",new JSONObject().put("agentId","actual"));d.accept(g,"agent.read",new JSONObject(),new JSONObject().put("agent042Facts",new JSONObject().put("agentId","invented")));assertEquals("actual",g.getJSONObject("context044").getJSONObject("agent042Facts").getString("agentId"));assertThrows(IllegalStateException.class,()->d.accept(g,"body.grab",new JSONObject(),new JSONObject().put("bodyGrab",new JSONObject().put("status","completed"))));}}
 @Test public void sourceFreeHostSuccessAndForeignChildrenAreRejected()throws Exception{try(var s=new WorkspaceStore(Files.createTempDirectory("domain044-forge-"))){var d=domain(s);var g=task("goal");assertThrows(IllegalStateException.class,()->d.accept(g,"goal.start",new JSONObject().put("passed",true),new JSONObject()));d.noteNative(g,"/api/goals/start",new JSONObject().put("id","actual-child"));assertThrows(IllegalStateException.class,()->d.accept(g,"goal.start",new JSONObject(),new JSONObject().put("ownedGoalId","foreign")));}}
 @Test public void reportMustHaveFrozenOriginalAssertionsAndExactSourceVersion()throws Exception{try(var s=new WorkspaceStore(Files.createTempDirectory("domain044-report-"))){var d=domain(s);var g=task("agent");var a=s.write(new JSONObject().put("title","Boundary report").put("files",new JSONObject().put("index.html","<h1>Unit admission fixture only</h1>")));var receipt=new JSONObject().put("snapshotSha256","a".repeat(64)).put("agentId","actual-agent").put("bootId","actual-boot");d.noteNative(g,"/api/agent042/report",new JSONObject().put("artifact",a).put("receipt",receipt));var weak=new JSONArray().put(new JSONObject().put("selector","body").put("expectCount",1));s.recordTest(new JSONObject().put("id",a.getString("id")).put("version",a.getInt("version")).put("steps",weak).put("checks",new JSONArray().put(new JSONObject().put("passed",true))));assertThrows(IllegalStateException.class,()->d.verifyReport(g));var fixed=ReportChecks044.expected("/api/agent042/report",new JSONObject().put("receipt",receipt),g,(r,x)->new JSONObject());var checks=new JSONArray();for(Object ignored:fixed)checks.put(new JSONObject().put("passed",true));s.recordTest(new JSONObject().put("id",a.getString("id")).put("version",a.getInt("version")).put("steps",fixed).put("checks",checks));d.verifyReport(g);}}
 @Test public void nativeWaitUsesActualChildAndRetainsItsIdentity()throws Exception{try(var s=new WorkspaceStore(Files.createTempDirectory("domain044-wait-"))){var status=new String[]{"running"};var d=new Domain044((r,a)->new JSONObject().put("id",a.getString("id")).put("status",status[0]),s);var g=task("creation");g.getJSONObject("context044").put("ownedGoalId","actual-child");g.put("wait044",new JSONObject().put("route","/api/goals/read").put("id","actual-child"));assertTrue(d.waitNative(g));status[0]="completed";assertFalse(d.waitNative(g));assertEquals(List.of("finish"),ChatPolicy044.allowed(g));assertEquals("actual-child",d.finish(g).getJSONObject("javaGoal").getString("id"));}}
 @Test public void interruptedChildCannotProduceSuccessfulCompletion()throws Exception{try(var s=new WorkspaceStore(Files.createTempDirectory("domain044-interrupted-"))){var d=new Domain044((r,a)->new JSONObject().put("status","interrupted").put("reason","Actual failure"),s);var g=task("creation").put("wait044",new JSONObject().put("route","/api/goals/read").put("id","retained"));assertThrows(IllegalStateException.class,()->d.waitNative(g));assertTrue(g.has("wait044"));}}
 @Test public void retainedSkillSourceAndForceDefaultsCannotBeSilentlyChanged()throws Exception{var p=new JSONObject().put("name","push-exact").put("version",2).put("kind","spatial-push-v1").put("defaults",new JSONObject().put("initialForceN",1).put("maxForceN",4));var scheduler=new Procedure044((r,a)->r.equals("/api/state")?new JSONObject().put("procedures",new JSONArray().put(p)):new JSONObject().put("id","new-native-child").put("args",a));var bindings=new JSONObject().put("push",new JSONObject().put("sceneId","fresh").put("objectId","crate").put("pusherId","pusher"));var input=new JSONObject().put("args",new JSONObject().put("name","push-exact").put("version",2).put("maxForceN",9)).put("bindings",bindings).put("request","Reuse procedure push-exact");assertThrows(IllegalArgumentException.class,()->scheduler.run(input));input.getJSONObject("args").remove("maxForceN");var actual=scheduler.run(input).getJSONObject("record").getJSONObject("args");assertEquals("fresh",actual.getString("sceneId"));assertEquals(2,actual.getInt("version"));input.getJSONObject("args").put("sceneId","foreign");assertThrows(IllegalArgumentException.class,()->scheduler.run(input));}
 @Test public void creationPromptsAreOwnedBoundedAndKeepSourceReserved(){var g=new JSONObject().put("title","Boundary").put("request","Create a working counter").put("checks",Agency043.counterChecks()).put("draft",2).put("source",new JSONObject().put("sample","x".repeat(50000))).put("previousFiles",new JSONObject().put("index.html","y".repeat(100000)));String prompt=CreationPlanner044.prompt(g,false);assertTrue(prompt.length()<=28000);assertTrue(prompt.contains("Do not write inputs/ files"));assertTrue(prompt.contains("FROZEN CHECKS"));assertTrue(CreationPlanner044.prompt(g,true).contains("BEFORE generating code"));}
 @Test public void retainedAppearancePolicyCannotChangeCategoryOrInstallDetectorOptions()throws Exception{var p=new JSONObject().put("name","cup-track").put("version",1).put("kind","browser-perception-v1").put("defaults",new JSONObject().put("mode","appearance").put("targetLabel","cup"));var scheduler=new Procedure044((r,a)->new JSONObject().put("procedures",new JSONArray().put(p)));var input=new JSONObject().put("args",new JSONObject().put("name","cup-track").put("version",1).put("targetLabel","person").put("frameId","actual"));assertThrows(IllegalArgumentException.class,()->scheduler.run(input));input.getJSONObject("args").put("targetLabel","cup").put("mode","fake");assertThrows(IllegalArgumentException.class,()->scheduler.run(input));}
 @Test public void actualQueueCompletionRecordsTheVerifiedReportInTheSameLearningEpisode()throws Exception{
  var turn=new java.util.concurrent.atomic.AtomicInteger();try(var f=new Agency043Test.Fixture(request->switch(turn.getAndIncrement()){case 0->Agency043Test.reply("agent.read",new JSONObject());case 1->Agency043Test.reply("agent.report",new JSONObject());default->Agency043Test.reply("finish",new JSONObject().put("summary","Fixture completion"));})){
   f.agency.install044(new Domain044((route,args)->route.equals("/api/state")?new JSONObject().put("scenes",new JSONArray()).put("datasets",new JSONArray()).put("procedures",new JSONArray()):new JSONObject(),f.store));var g=f.start("Read the Java heartbeat","workbench");f.agency.tick();f.agency.tick();var read=f.claim();var facts=new JSONObject().put("agentId","actual-unit-boundary");f.agency.nativeReceipt044(g.getString("id"),read.getString("nonce"),"/api/agent042/state",facts);f.agency.acknowledge(f.authority(read).put("context",new JSONObject().put("agent042Facts",facts)).put("result",facts));
   f.agency.tick();var report=f.claim();var a=f.store.write(new JSONObject().put("title","Unit receipt boundary").put("files",new JSONObject().put("index.html","<p>Explicit admission fixture; separate tests run Chromium</p>")));var receipt=new JSONObject().put("snapshotSha256","c".repeat(64)).put("agentId","actual-unit-boundary").put("bootId","actual-unit-boot");f.agency.nativeReceipt044(g.getString("id"),report.getString("nonce"),"/api/agent042/report",new JSONObject().put("artifact",a).put("receipt",receipt));var steps=ReportChecks044.expected("/api/agent042/report",new JSONObject().put("receipt",receipt),f.agency.read(g.getString("id")),(r,x)->new JSONObject());var checks=new JSONArray();for(Object ignored:steps)checks.put(new JSONObject().put("passed",true));f.store.recordTest(new JSONObject().put("id",a.getString("id")).put("version",1).put("steps",steps).put("checks",checks));f.agency.acknowledge(f.authority(report).put("context",new JSONObject()).put("result",new JSONObject()));f.agency.tick();var done=f.agency.read(g.getString("id"));assertEquals("completed",done.getString("status"));assertEquals("verified",done.getString("outcome"));var episode=f.learning.read("episode",done.getString("episodeId"));assertEquals("verified",episode.getString("status"));assertEquals(a.getString("id"),episode.getJSONArray("steps").getJSONObject(0).getString("artifactId"));
  }
 }
}
